arguments.command:
cd /tmp/sv-163ecaf39b9a4c92bf38bdadba69d093/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_pkgs(baseline)
a = get_pkgs(after)
all_keys = sorted(set(list(b.keys()) + list(a.keys())))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k, bv, av))
    else:
        unchanged.append((k, bv))

print('=== CHANGES ===')
for (proj, fw, pkg), bv, av in changes:
    print(f'  {proj} ({fw}): {pkg} {bv} -> {av}')
print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')
"

